// Use Mouse to draw Mood Ring trails.
//
// Keyboard Commands:
//
// <Q>,<W> alter Feed Rate
// <A>,<S> alter Kill Rate
// <Z>,<X> alter Diffusion rate A
// <E>,<R> alter Diffusion rate B
// <D>,<F> alter Scale
//
// <Return> Reset everything 
// <Space>  Reset just the Population
//--------------------------------------------------------------

vec3 jetColorMap(float t) { // 0 ... 1
    return clamp(vec3(1.5) - abs(4.0 * vec3(t) + vec3(-3., -2., -1.)), vec3(0.), vec3(1.));
}

void drawGrid(inout vec4 O, vec2 U) {
    U /= iResolution.xy;  // 0 ... 1

    ivec2 addr = ivec2(int(float(GRIDX) * U.x),int(float(GRIDY) * U.y));
    vec4 data = fetchData(iChannel0, addr);

    O.xyz = jetColorMap(fract(data.x));
}

void mainImage(out vec4 O, vec2 U) {
    drawGrid(O,U);

    getSettings(iChannel0);
    if(iFrame - int(qFrame) < 20) 
        displayData(iChannel2,iResolution.xy,O,U);
}

void saveSettings(inout vec4 fragColor,vec2 fragCoord) {
    for(int i=0;i<ADDR_COUNT;++i)
        if(storeDataAddr(fragCoord, addrList[i])) {
            fragColor.xyz = q[i];
            return;
        }
}

// ----------------------------------------------------------

const float RNDCHANCE = 0.01;
const float YSTART = 0.83;

void resetDiffusion(inout vec4 color,vec2 coord) {
    ivec2 adr = ivec2(coord);
    if(adr.x < GRIDX && adr.y < GRIDY) {
        color.x = 1.; 
        color.y = (rndStart(coord,iTime) < RNDCHANCE) ? YSTART : 0.;
    }
}

void reset(inout vec4 color,vec2 coord) {
    ivec2 adr = ivec2(coord);
    if(adr.x < GRIDX && adr.y < GRIDY) {
        color.x = 1.;
        color.y = (rndStart(coord,iTime) < RNDCHANCE) ? YSTART : 0.;
    }
}

// ----------------------------------------------------------

#define hk 0.0042 
#define adjacentWeight 0.2
#define diagonalWeight (adjacentWeight / 1.414)
#define centerWeight -(adjacentWeight * 4.0 + diagonalWeight * 4.0 + hk * 2.)

#define cellV1(ix,iy) texelFetch(iChannel1,ivec2(ix,iy),0).x
#define cellV2(ix,iy) texelFetch(iChannel1,ivec2(ix,iy),0).y

void evolveCell(inout vec4 color, vec2 coord) {
    ivec2 adr = ivec2(coord);
    vec4 cell = texelFetch(iChannel1,adr,0); 

    float qq = 100. / qScale;

    float a = cell.x;
    float b = cell.y;

    float k = qKillRate + qKillRate * a / qq;
    float f = qFeedRate + qFeedRate * a / qq;

    // ------------------------------------------------------------
    // neighboring pixels, wrapping around edges
    int xp = (GRIDX + adr.x - 1) % GRIDX;
    int xn = (GRIDX + adr.x + 1) % GRIDX;
    int yp = (GRIDY + adr.y - 1) % GRIDY;
    int yn = (GRIDY + adr.y + 1) % GRIDY;

    // A diffusion
    float dda = a * centerWeight;
    dda += cellV1(xn, yn) * diagonalWeight;
    dda += cellV1(xp, yn) * diagonalWeight;
    dda += cellV1(xn, yp) * diagonalWeight;
    dda += cellV1(xp, yp) * diagonalWeight;
    dda += cellV1(adr.x, yn) * adjacentWeight;
    dda += cellV1(adr.x, yp) * adjacentWeight;
    dda += cellV1(xn, adr.y) * adjacentWeight + hk;
    dda += cellV1(xp, adr.y) * adjacentWeight + hk;

    // B diffusion
    float ddb = b * centerWeight;
    ddb += cellV2(xn, yn) * diagonalWeight;
    ddb += cellV2(xp, yn) * diagonalWeight;
    ddb += cellV2(xn, yp) * diagonalWeight;
    ddb += cellV2(xp, yp) * diagonalWeight;
    ddb += cellV2(adr.x, yn) * adjacentWeight;
    ddb += cellV2(adr.x, yp) * adjacentWeight;
    ddb += cellV2(xn, adr.y) * adjacentWeight + hk;
    ddb += cellV2(xp, adr.y) * adjacentWeight + hk;

    // reaction diffusion formula
    float da = qDiffusionRateA * dda - a * b * b + f * (1.0 - a);
    float db = qDiffusionRateB * ddb + a * b * b - (f + k) * b;

    color.x = a + da * qScale;
    color.y = b + db * qScale;
}

// ----------------------------------------------------------

bool keyClick(int ascii,sampler2D channel) {
	return (texture(channel,vec2((.5+float(ascii))/256.,0.25)).x > 0.);
}

bool getKeyState(int keyCode,sampler2D channel) {
    bool keyPressed = bool(texelFetch(channel, ivec2(keyCode,0), 0).x != 0.);
    if(keyPressed) qFrame = float(iFrame);
    return keyPressed;
}

// ----------------------------------------------------------

void wallPixel(vec2 base, int x,int y,inout vec4 fragColor, vec2 fragCoord) {
    ivec2 adr = ivec2(int(base.x)+x,int(base.y)+y);
    if(storeDataAddr(fragCoord,adr)) 
       fragColor.xy = min(fragColor.xy * 2., vec2(0.6));
}

// ----------------------------------------------------------

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if(iFrame < 2 || keyClick(13,iChannel3)) { // coldstart or <Return>
        qFeedRate = 0.02;
        qKillRate = 0.079;
        qDiffusionRateA = 1.1010;
        qDiffusionRateB = 0.4;
        qScale = 0.79;
        saveSettings(fragColor,fragCoord);
        reset(fragColor,fragCoord);
        return;
    }

    getSettings(iChannel0); 
    fragColor = fetchData(iChannel0, ivec2(fragCoord));

    if(keyClick(32,iChannel3)) { // <Space>
        resetDiffusion(fragColor,fragCoord);
        return;
    }

    if(fragCoord.x < float(GRIDX) && fragCoord.y < float(GRIDY)) 
            evolveCell(fragColor,fragCoord);     

    // adding walls ------------------------------------
    if(iMouse.z > 0.) {     // mouse down or dragged
        int width = 10;
        vec2 mPos = vec2(GRIDX,GRIDY) * iMouse.xy / iResolution.xy; // mouse as grid position
        for(int x=-width;x<=width;++x)
            for(int y=-width;y<=width;++y)
                wallPixel(mPos,x,y,fragColor,fragCoord);
    }

    // -----------------------------------------------------------------------------------
    if(getKeyState(81,iChannel3)) qFeedRate = clamp(qFeedRate - 0.001,0.01,0.2); // Q
    if(getKeyState(87,iChannel3)) qFeedRate = clamp(qFeedRate + 0.001,0.01,0.2); // W
    if(getKeyState(65,iChannel3)) qKillRate = clamp(qKillRate - 0.001,0.01,0.2); // A
    if(getKeyState(83,iChannel3)) qKillRate = clamp(qKillRate + 0.001,0.01,0.2); // S
    if(getKeyState(90,iChannel3)) qDiffusionRateA = clamp(qDiffusionRateA - 0.001,0.1,1.3); // Z
    if(getKeyState(88,iChannel3)) qDiffusionRateA = clamp(qDiffusionRateA + 0.001,0.1,1.3); // X
    if(getKeyState(69,iChannel3)) qDiffusionRateB = clamp(qDiffusionRateB - 0.001,0.1,1.3); // E
    if(getKeyState(82,iChannel3)) qDiffusionRateB = clamp(qDiffusionRateB + 0.001,0.1,1.3); // R
    if(getKeyState(68,iChannel3)) qScale = clamp(qScale - 0.01,0.01,10.); // D
    if(getKeyState(70,iChannel3)) qScale = clamp(qScale + 0.01,0.01,10.); // F

    saveSettings(fragColor,fragCoord); 
}

#define GRIDX  300  // terrain size
#define GRIDY  (GRIDX * 7 / 10)

#define qFeedRate       q[0].x
#define qKillRate       q[0].y
#define qDiffusionRateA q[0].z
#define qDiffusionRateB q[1].x
#define qScale          q[1].y
#define qFrame          q[1].z  // frame# when edits were made
const int ADDR_COUNT =    2;

vec3[ADDR_COUNT] q;

const ivec2 Q0 = ivec2( 0,GRIDY+1);
const ivec2 Q1 = ivec2( 1,GRIDY+1);
const ivec2[ADDR_COUNT] addrList = ivec2[](Q0,Q1);

#define fetchData(buf, addr) texelFetch(buf, addr, 0)
#define storeDataAddr(buf_pos, addr) ivec2(buf_pos) == addr

void getSettings(sampler2D channel) { 
    for(int i=0;i<ADDR_COUNT;++i) 
        q[i] = texelFetch(channel, addrList[i],0).xyz;
}

// ========================================================================
// https://www.shadertoy.com/view/MtfGWM

float previousRnd = 0.;

float rnd(vec2 c) { return fract(sin(dot(vec2(1.317,19.753),c))*413.7972); } // 0...1

float rndStart(vec2 coord, float t) {  // 0...1
	previousRnd += rnd(coord.xy + vec2(t * 217.0));
    return previousRnd;
}

// =======================================================================
// font display technique I learned from cmgz's "The Chaos factory".  Thank you sir.
// https://www.shadertoy.com/view/XfdyRX

float drawChar(sampler2D chan,vec2 char_p, int char_id) { // https://www.shadertoy.com/view/llySRh
    if (char_p.x < .0 || char_p.x>1. || char_p.y<0. || char_p.y>1.) return 0.;
    vec2 p = char_p/16.; 
    return textureGrad(chan, p + fract(vec2(char_id,15-char_id/16)/16.), dFdx(p), dFdy(p)).x;
}

void printChar(sampler2D chan,inout vec2 position,int ascii,inout float result) {
    result = max(result, drawChar(chan,position,ascii));
    position.x -= 0.5;
}

#define printString(chan,position,asciiArray,result) for(int i=0;i< asciiArray.length();i++) printChar(chan,position,asciiArray[i],result);

void printInt(sampler2D chan,inout vec2 position,int value, inout float result) {
    int[8] digits;
    int count = 0;
    if(value < 0) { printChar(chan,position,45,result);  value = -value; }    
    for(;;) {
        digits[count] = value % 10;        
        if(++count >= 8) break;        
        value /= 10;        
        if(value == 0) break;
    }

    for(int i = count-1; i >= 0; i--)
        printChar(chan,position,48+digits[i],result);
}

void printFloat(sampler2D chan,inout vec2 position,float value, inout float result) {
    if(value < 0.) { printChar(chan,position,45,result); value = -value; }        
    int i = int(value);
    printInt(chan,position,i,result);
    printChar(chan,position,46,result);
    i = int(fract(value) * 10000.);
    printInt(chan,position,i,result);
}

// 0123456789 +-.[]  48..57,  43,45,46,91,92
// A65,B66,C67,D68, E69, F70, G71, H72, I73, J74, K75, L76, M77, N78, O79, P80, Q81, R82, S83, T84, U85, V86, W87, X88, Y89, Z90
// a97,b98,c99,d100,e101,f102,g103,h104,i105,j106,k107,l108,m109,n110,o111,p112,q113,r114,s115,t116,u117,v118,w119,x120,y121,z122

const int FeedRate[] = int[](81,46,87,32,70,101,101,100,82,97,116,101);
const int KillRate[] = int[](65,46,83,32,75,105,108,108,82,97,116,101);
const int DiffusionA[] = int[](90,46,88,32,68,105,102,102,117,115,105,111,110,32,65);
const int DiffusionB[] = int[](69,46,82,32,68,105,102,102,117,115,105,111,110,32,66);
const int Scale[] = int[](68,46,70,32,83,99,97,108,101);

const float textSize = 10.; // smaller value -> larger text   
const vec2 textUL = vec2(1.78,-0.88);

#define Entry(legend,value) \
    p2 = p; \
    char_d = 0.; \
    printString(channel,p2,legend,char_d); \
    printChar(channel,p2,32,char_d); \
    printFloat(channel,p2,value,char_d); \
    if(char_d > 0.5) { O.xyz = vec3(1.); return; } \
    p.y += 0.84;    

void displayData(sampler2D channel, vec2 R, inout vec4 O, vec2 U) {
    vec2 uv = (2.0 * U - R.xy)/R.y;
    vec2 p2,p = textSize * (textUL + uv);
    float char_d;

    if(uv.x < -0.6 && uv.y > .5) O = vec4(0.);    // background

    Entry(FeedRate, qFeedRate);
    Entry(KillRate, qKillRate);
    Entry(DiffusionA, qDiffusionRateA);
    Entry(DiffusionB, qDiffusionRateB);
    Entry(Scale, qScale);
}

// copy all grid pixels from BufferA
// will serve as 'old' data when evolving cells

void mainImage( out vec4 O, in vec2 U) {
    if(U.x < float(GRIDX) && U.y < float(GRIDY))
        O = texelFetch(iChannel0,ivec2(U),0);
}
